class ReviewRequestsScreen extends StatelessWidget { const ReviewRequestsScreen({super.key}); @override Widget build(BuildContext context){final s=BorrowerAppState.instance;return AnimatedBuilder(animation:s,builder:(_,__)=>Scaffold(body:Container(width:double.infinity,height:double.infinity,decoration:BoxDecoration(gradient:LinearGradient(colors:[AppPalette.bg1,AppPalette.bg2,AppPalette.bg3],begin:Alignment.topLeft,end:Alignment.bottomRight)),child:SafeArea(child:Column(children:[Padding(padding:const EdgeInsets.symmetric(horizontal:40,vertical:20),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Image.asset('assets/images/rushd_log.png',width:180,errorBuilder:(_,__,___)=>AppText('Rushd',style:TextStyle(color:Colors.white,fontSize:22,fontWeight:FontWeight.bold))),AppText('Review Requests',style:TextStyle(color:Colors.white,fontSize:28,fontWeight:FontWeight.bold)),Container(padding:const EdgeInsets.symmetric(horizontal:15,vertical:8),decoration:BoxDecoration(color:Colors.lightBlue.withOpacity(.2),borderRadius:BorderRadius.circular(20)),child:AppText('New Requests: ${s.pending}',style:const TextStyle(color:Colors.white)))])),Expanded(child:Padding(padding:const EdgeInsets.symmetric(horizontal:40,vertical:20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[IconButton(icon:const Icon(Icons.arrow_back,color:Colors.white),onPressed:()=>Navigator.pop(context)),const SizedBox(width:10),AppText('Review Requests',style:TextStyle(color:Colors.white,fontSize:28,fontWeight:FontWeight.bold))]),const SizedBox(height:20),if(s.requests.isEmpty) _empty() else Expanded(child:ListView(children:s.requests.map((r)=>_request(r)).toList()))])))])))));}
