Widget _request(BorrowerRequest r)=>Container(margin:const EdgeInsets.only(bottom:14),padding:const EdgeInsets.all(22),decoration:BoxDecoration(color:Colors.white.withOpacity(.08),borderRadius:BorderRadius.circular(20)),child:Row(children:[const Icon(Icons.person_outline,color:Colors.lightBlue,size:34),const SizedBox(width:16),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[AppText(BorrowerAppState.instance.fullName,style:const TextStyle(color:Colors.white,fontSize:17,fontWeight:FontWeight.bold)),const SizedBox(height:5),AppText('${r.loanType} • SAR ${r.amount} • ${r.bank}',style:const TextStyle(color:Colors.white70))])),Container(padding:const EdgeInsets.symmetric(horizontal:14,vertical:8),decoration:BoxDecoration(color:Colors.amber.withOpacity(.16),borderRadius:BorderRadius.circular(18)),child:AppText(r.status,style:const TextStyle(color:Colors.amberAccent,fontWeight:FontWeight.bold)))]));}
